122	  @Override
123	  public void loadInstantDetailsInMemory(String startTs, String endTs) {
124	    loadInstants(startTs, endTs);
125	  }
126	
127	  @Override
128	  public void loadCompletedInstantDetailsInMemory() {
129	    loadInstants(null, true,
130	        record -> {
131	          // Very old archived instants don't have action state set.
132	          Object action = record.get(ACTION_STATE);
133	          return action == null || org.apache.hudi.common.table.timeline.HoodieInstant.State.COMPLETED.toString().equals(action.toString());
134	        });
135	  }
136	
137	  @Override
138	  public void loadCompactionDetailsInMemory(String compactionInstantTime) {
139	    loadCompactionDetailsInMemory(compactionInstantTime, compactionInstantTime);
140	  }
141	
142	  @Override
143	  public void loadCompactionDetailsInMemory(String startTs, String endTs) {
144	    // load compactionPlan
145	    loadInstants(new HoodieArchivedTimeline.TimeRangeFilter(startTs, endTs), true,
146	        record -> {
147	          // Older files don't have action state set.
148	          Object action = record.get(ACTION_STATE);
149	          return record.get(ACTION_TYPE_KEY).toString().equals(HoodieTimeline.COMPACTION_ACTION)
150	              && (action == null || org.apache.hudi.common.table.timeline.HoodieInstant.State.INFLIGHT.toString().equals(action.toString()));
151	        });
152	  }
153	
154	  @Override
155	  public void clearInstantDetailsFromMemory(String instantTime) {
156	    this.readCommits.remove(instantTime);
157	  }
158	
159	  @Override
160	  public void clearInstantDetailsFromMemory(String startTs, String endTs) {
161	    this.findInstantsInRange(startTs, endTs).getInstants().forEach(instant ->
162	        this.readCommits.remove(instant.requestedTime()));
163	  }
