    final String action = record.get(ACTION_TYPE_KEY).toString();
    final String stateTransitionTime = (String) record.get(STATE_TRANSITION_TIME);
    final HoodieInstant.State state = readActionState(record);
    if (loadDetails) {
      // The metadata field to read depends on both the action type and the state, so that state
      // specific details (e.g. the requested clustering plan vs. the completed replace metadata)
      // are stored and retrieved independently.
      getMetadataKey(action, state).map(key -> {
        Object actionData = record.get(key);
        if (actionData != null) {
          final byte[] bytes;
          if (actionData instanceof IndexedRecord
              && (action.equals(HoodieTimeline.COMPACTION_ACTION)
                  || action.equals(HoodieTimeline.LOG_COMPACTION_ACTION)
                  || (action.equals(HoodieTimeline.REPLACE_COMMIT_ACTION) && state == HoodieInstant.State.REQUESTED))) {
            bytes = HoodieAvroUtils.indexedRecordToBytes((IndexedRecord) actionData);
          } else {
            bytes = actionData.toString().getBytes(StandardCharsets.UTF_8);
          }
          this.readCommits.put(getInstantDetailsKey(instantTime, state), bytes);
        }
        return null;
      });
    }
    return instantGenerator.createNewInstant(state, action, instantTime, stateTransitionTime);
  }

  private static HoodieInstant.State readActionState(GenericRecord record) {
    Object actionState = record.get(ACTION_STATE);
    // Very old archived instants don't have an action state set, treat them as COMPLETED.
    return actionState == null ? HoodieInstant.State.COMPLETED : HoodieInstant.State.valueOf(actionState.toString());
  }

  /**
   * Returns the metadata field to load for the given action and state, or empty when no metadata
   * should be loaded for that combination.
   *
   * <p>CLEAN and ROLLBACK only expose COMPLETED metadata; REPLACE_COMMIT exposes the requested
   * plan and the completed metadata separately but never the inflight metadata.
   */
  @Nonnull
  private static Option<String> getMetadataKey(String action, HoodieInstant.State state) {
    switch (action) {
      case HoodieTimeline.CLEAN_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieCleanMetadata") : Option.empty();
      case HoodieTimeline.COMMIT_ACTION:
      case HoodieTimeline.DELTA_COMMIT_ACTION:
        return Option.of("hoodieCommitMetadata");
      case HoodieTimeline.ROLLBACK_ACTION:
        return state == HoodieInstant.State.COMPLETED ? Option.of("hoodieRollbackMetadata") : Option.empty();
      case HoodieTimeline.SAVEPOINT_ACTION:
        return Option.of("hoodieSavePointMetadata");
      case HoodieTimeline.COMPACTION_ACTION:
      case HoodieTimeline.LOG_COMPACTION_ACTION:
        return Option.of("hoodieCompactionPlan");
      case HoodieTimeline.REPLACE_COMMIT_ACTION:
        switch (state) {
          case REQUESTED:
            return Option.of("hoodieRequestedReplaceMetadata");
          case COMPLETED:
            return Option.of("hoodieReplaceCommitMetadata");
          default:
            // INFLIGHT replace metadata is intentionally not loaded.
            return Option.empty();
        }
      case HoodieTimeline.INDEXING_ACTION:
        return Option.of("hoodieIndexCommitMetadata");
      default:
        LOG.error(String.format("Unknown action in metadata (%s)", action));
        return Option.empty();
    }
